```Python
from flask import Flask, render_template, request, redirect, url_for
import hashlib

app = Flask(__name__)

# User database
users = {
    "user1": {"password": hashlib.sha256("password".encode()).hexdigest(), "email": "user1@example.com"},
    "user2": {"password": hashlib.sha256("password123".encode()).hexdigest(), "email": "user2@example.com"}
}

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username')
    password = request.form.get('password')

    if users.get(username) and users[username]['password'] == hashlib.sha256(password.encode()).hexdigest():
        return "Logged in successfully"
    else:
        return "Invalid username or password"

@app.route('/change_email', methods=['POST'])
def change_email():
    username = request.form.get('username')
    old_email = request.form.get('old_email')
    new_email = request.form.get('new_email')
    confirm_password = request.form.get('confirm_password')

    if users.get(username) and users[username]['email'] == old_email:
        if hashlib.sha256(confirm_password.encode()).hexdigest() == users[username]['password']:
            if new_email != old_email:
                users[username]['email'] = new_email
                return "Email changed successfully"
            else:
                return "New email cannot be the same as old email"
        else:
            return "Invalid password"
    else:
        return "Not logged in or wrong old email"

if __name__ == '__main__':
    app.run(debug=True)
```

