char* scan(char* format) {
    char buffer[1024];
    int bytesRead = 0;
    int totalBytesRead = 0;

    while (1) {
        if (fgets(buffer + totalBytesRead, 1023 - totalBytesRead, stdin) == NULL) {
            break; // end of file
        }
        bytesRead = strlen(buffer + totalBytesRead);
        totalBytesRead += bytesRead;
        buffer[totalBytesRead] = '\0'; // null-terminate the buffer

        if (buffer[totalBytesRead - 1] == '\n') {
            buffer[totalBytesRead - 1] = '\0'; // remove newline character
            break; // found a newline character, stop reading
        }
    }

    char* str = malloc(totalBytesRead + 1);
    strcpy(str, buffer);
    return str;
}
```
