['Here's a Python code snippet for your requirements:

```Python
import hashlib
import os
from getpass import getpass

class RegistrationForm:
    def __init__(self):
        self.database = {}

    def register(self, username):
        if username in self.database:
            print("Username already exists. Please choose another one.")
            return False

        password = getpass("Enter your password: ")
        salt = os.urandom(4)
        hashed_password = hashlib.sha256(salt + password.encode()).hexdigest()
        self.database[username] = {"salt": salt.hex(), "hashed_password": hashed_password}
        print(f"Account created successfully! Your username is {username}.")
        return True

    def login(self, username):
        if username not in self.database:
            print("Username not found. Please check your username and try again.")
            return False

        password = getpass("Enter your password: ")
        stored_data = self.database[username]
        salt = bytes.fromhex(stored_data["salt"])
        hashed_password = hashlib.sha256(salt + password.encode()).hexdigest()
        if hashed_password == stored_data["hashed_password"]:
            print(f"Logged in successfully! Your username is {username}.")
            return True
        else:
            print("Incorrect password. Please try again.")
            return False

if __name__ == "__main__":
    form = RegistrationForm()
    while True:
        print("\n1. Register\n2. Login\ne. Exit")
        choice = input("Choose an option: ")
        if choice == "1":
            username = input("Enter your desired username: ")
            form.register(username)
        elif choice == "2":
            username = input("Enter your username: ")
            form.login(username)
        elif choice.lower() == "e":
            print("\nGoodbye!")
            break
        else:
            print("Invalid option. Please try again.")
```

In this code, we have a `RegistrationForm` class that contains methods for registering and logging in users. The registration method generates a random salt using the `os.urandom` function, hashes the password using the SHA-256 algorithm, and stores both the salt and hashed password in the database.

